//! Bounded admitted pull-page sequence. Exact row parsing/SQL stays platform.
#[derive(Debug,PartialEq,Eq)]pub enum Error<E>{Callback(E),Invalid,Overflow}
pub trait Backend{type Error;
 fn ready(&mut self)->Result<i32,Self::Error>;fn cursor(&mut self)->Result<i64,Self::Error>;
 fn remote(&mut self,i:i32)->Result<i64,Self::Error>;fn sequence(&mut self,i:i32)->Result<i64,Self::Error>;fn inspect(&mut self,i:i32)->Result<(),Self::Error>;fn server(&mut self,i:i32)->Result<i64,Self::Error>;
 fn pending(&mut self,i:i32)->Result<bool,Self::Error>;fn conflict(&mut self,i:i32)->Result<(),Self::Error>;
 fn prepare(&mut self,i:i32)->Result<(),Self::Error>;fn local(&mut self,i:i32)->Result<i64,Self::Error>;fn domain(&mut self,i:i32)->Result<(),Self::Error>;fn revision(&mut self,i:i32,next:i64)->Result<(),Self::Error>;
 fn advance(&mut self,i:i32,sequence:i64)->Result<(),Self::Error>;
}
pub fn execute<B:Backend>(b:&mut B)->Result<i32,Error<B::Error>>{
 let count=b.ready().map_err(Error::Callback)?;if !(0..=100).contains(&count){return Err(Error::Invalid)}let mut cursor=b.cursor().map_err(Error::Callback)?;let mut applied=0;
 for i in 0..count{let remote=b.remote(i).map_err(Error::Callback)?;let sequence=b.sequence(i).map_err(Error::Callback)?;if remote<=0||sequence<=cursor{return Err(Error::Invalid)}b.inspect(i).map_err(Error::Callback)?;let server=b.server(i).map_err(Error::Callback)?;
  if remote>server{if b.pending(i).map_err(Error::Callback)?{b.conflict(i).map_err(Error::Callback)?;}else{b.prepare(i).map_err(Error::Callback)?;let local=b.local(i).map_err(Error::Callback)?;let next=local.checked_add(1).ok_or(Error::Overflow)?;b.domain(i).map_err(Error::Callback)?;b.revision(i,next).map_err(Error::Callback)?;applied+=1;}}
  b.advance(i,sequence).map_err(Error::Callback)?;cursor=sequence;
 }Ok(applied)
}
#[cfg(test)]mod tests{use super::*;struct P{trace:Vec<String>,cut:usize,count:i32,remote:i64,server:i64,sequence:i64,cursor:i64,local:i64,pending:bool}impl P{fn new()->Self{Self{trace:vec![],cut:0,count:2,remote:3,server:1,sequence:5,cursor:0,local:7,pending:false}}fn hit(&mut self,s:String)->Result<(),usize>{self.trace.push(s);if self.trace.len()==self.cut{Err(self.cut)}else{Ok(())}}}impl Backend for P{type Error=usize;
fn ready(&mut self)->Result<i32,usize>{self.hit("ready".into())?;Ok(self.count)}fn cursor(&mut self)->Result<i64,usize>{self.hit("cursor".into())?;Ok(self.cursor)}fn remote(&mut self,i:i32)->Result<i64,usize>{self.hit(format!("remote{i}"))?;Ok(self.remote)}fn sequence(&mut self,i:i32)->Result<i64,usize>{self.hit(format!("sequence{i}"))?;Ok(self.sequence+i as i64)}fn inspect(&mut self,i:i32)->Result<(),usize>{self.hit(format!("inspect{i}"))}fn server(&mut self,i:i32)->Result<i64,usize>{self.hit(format!("server{i}"))?;Ok(self.server)}fn pending(&mut self,i:i32)->Result<bool,usize>{self.hit(format!("pending{i}"))?;Ok(self.pending)}fn conflict(&mut self,i:i32)->Result<(),usize>{self.hit(format!("conflict{i}"))}fn prepare(&mut self,i:i32)->Result<(),usize>{self.hit(format!("prepare{i}"))}fn local(&mut self,i:i32)->Result<i64,usize>{self.hit(format!("local{i}"))?;Ok(self.local)}fn domain(&mut self,i:i32)->Result<(),usize>{self.hit(format!("domain{i}"))}fn revision(&mut self,i:i32,n:i64)->Result<(),usize>{assert_eq!(n,self.local+1);self.hit(format!("revision{i}"))}fn advance(&mut self,i:i32,s:i64)->Result<(),usize>{assert_eq!(s,self.sequence+i as i64);self.hit(format!("advance{i}"))}}
#[test]fn all_branches_exact_order_every_callback_cutoff(){for branch in 0..3{let mut p=P::new();p.pending=branch==1;if branch==2{p.server=3;}assert_eq!(execute(&mut p),Ok(if branch==0{2}else{0}));let trace=p.trace;for cut in 1..=trace.len(){let mut q=P::new();q.pending=branch==1;if branch==2{q.server=3;}q.cut=cut;assert_eq!(execute(&mut q),Err(Error::Callback(cut)));assert_eq!(q.trace,trace[..cut]);}}}
#[test]fn bounds_signed_values_overflow_and_no_effect_invalid_sequence(){for n in [-1,101]{let mut p=P::new();p.count=n;assert_eq!(execute(&mut p),Err(Error::Invalid));assert_eq!(p.trace,vec!["ready"]);}let mut p=P::new();p.count=0;assert_eq!(execute(&mut p),Ok(0));assert_eq!(p.trace,vec!["ready","cursor"]);for(local,cursor)in[(i64::MIN,i64::MIN),(-1,-3),(i64::MAX-1,0)]{let mut p=P::new();p.local=local;p.cursor=cursor;assert_eq!(execute(&mut p),Ok(2));}let mut p=P::new();p.local=i64::MAX;assert_eq!(execute(&mut p),Err(Error::Overflow));assert_eq!(p.trace.last().unwrap(),"local0");for(remote,seq)in[(0,1),(3,0)]{let mut p=P::new();p.remote=remote;p.sequence=seq;assert_eq!(execute(&mut p),Err(Error::Invalid));assert_eq!(p.trace.last().unwrap(),"sequence0");}}
#[test]fn full_hundred_and_empty_page(){for n in [0,1,100]{let mut p=P::new();p.count=n;assert_eq!(execute(&mut p),Ok(n));}}}
